from random import *

def clecryptage():
    """
    Cette fonction s'occupe de créer une clé de cryptage,
    dans les valeurs d'une liste correspondant a un début et a la fin des 10 000 première décimales de Pi
    On récupère 5 nombres qui ce suivent et forme notre clé.
    """
    cle=[]
    Departcle=randint(0,1830-5)
    decipi=""
    for i in range(5):
        cle.append(decipi[Departcle+i])
    return cle

def Encrypteur():
    """
    Cette fonction s'occupe de crypter notre message,
    elle récupère la clé de cryptage aléatoire créé pour faire une roue de césar avec les caract swap.
    puis écrit la clé au début du message suivi d'un # pour séparer la clé du message.
    """
    texteswap=""
    cle="".join(clecryptage())
    cleint=int(cle[0])+int(cle[1])+int(cle[2])+int(cle[3])+int(cle[4])
    texteswap+=cle+"#"
    caractere="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ ,;/!%éàèêîôöïë()[]=+-@&1234567890*$_<>|~'.?"
    caractereswap="Hride4xSB UyVg._IöTZbvp@Fé5D78nP~,=jJ6RNo!lè'm[K?tX+O*$|qGWaêzQMôEYsîL-ï%/<ë;3C2(9wA>1)]&àcukh0f"
    caractereswapcle=caractereswap[cleint:] + caractereswap[:cleint]
    texte = str(input("Saisir votre texte : "))
    for i in range(len(texte)):
        for y in range(96):
            if texte[i]==caractere[y]:
                texteswap+=caractereswapcle[y]
                break
            else:
                if y==95:
                    texteswap+=texte[i]
    
    VerEncrypt=texteswap
    return VerEncrypt